package com.citacloud.app.services; import net.sf.jasperreports.engine.*; import net.sf.jasperreports.engine.data.JRMapCollectionDataSource; import org.springframework.core.io.ClassPathResource; import org.springframework.stereotype.Service; import java.io.InputStream; import java.util.*; @Service public class JasperPdfService {public byte[] generar(String plantilla,Map<String,Object> p,List<Map<String,Object>> filas){try(InputStream in=new ClassPathResource("reportes/"+plantilla+".jrxml").getInputStream()){Collection<Map<String,?>> datos=new ArrayList<>(filas);return JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(JasperCompileManager.compileReport(in),p,new JRMapCollectionDataSource(datos)));}catch(Exception e){throw new IllegalStateException("No se pudo generar el reporte Jasper.",e);}}}
